// Mock radio Worker for the spike harness.
// Serves the shared queue-state contract (docs/shared-queue-contract.md)
// on the same paths the real radio Worker will serve, so the Worker-side
// radio client (src/radio.js) can be exercised without the radio existing:
//   GET /radio/status  -> get_status() shape + upNext + stream
//   GET /radio/audio   -> an Ogg Opus file (generated by the harness)

import http from 'node:http';
import fs from 'node:fs';

export function startMockRadio({ port, opusFile }) {
  const status = {
    nowPlaying: {
      title: 'Spike Tone (Test Track)',
      artist: 'Lucifer Test Bench',
      source: 'playlist',
      file: 'spike-tone.opus',
      played_at: new Date().toISOString(),
      audioUrl: `http://127.0.0.1:${port}/radio/audio`,
    },
    queueLength: 2,
    playlistLength: 13,
    submissionsPending: 2,
    upNext: [
      { title: 'Submission One', artist: 'Test Artist', source: 'submission' },
      { title: 'Submission Two', artist: 'Test Artist', source: 'submission' },
      { title: 'Playlist Track', artist: 'TizWildin', source: 'playlist' },
    ],
    stream: { mode: 'loop', hlsUrl: null, audioUrl: `http://127.0.0.1:${port}/radio/audio` },
  };

  const server = http.createServer((req, res) => {
    if (req.url === '/radio/status') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(status));
    } else if (req.url === '/radio/audio' && opusFile && fs.existsSync(opusFile)) {
      res.writeHead(200, { 'Content-Type': 'audio/ogg' });
      fs.createReadStream(opusFile).pipe(res);
    } else {
      res.writeHead(404);
      res.end('not found');
    }
  });
  return new Promise((resolve) => server.listen(port, '127.0.0.1', () => resolve(server)));
}
